import 'package:flutter/material.dart';
import '../../services/supabase_config.dart';
import '../../widgets/app_ui.dart';

class GroupsScreen extends StatefulWidget {
  const GroupsScreen({super.key});
  @override State<GroupsScreen> createState() => _GroupsScreenState();
}

class _GroupsScreenState extends State<GroupsScreen> {
  bool _loading = true;
  List<Map<String, dynamic>> _groups = [];
  @override void initState() { super.initState(); _load(); }
  Future<void> _load() async { try { final data = await supabase.from('groups').select('*, profiles!groups_owner_id_fkey(username, full_name)').order('created_at', ascending: false); if (mounted) setState(() { _groups = (data as List).map((e) => Map<String, dynamic>.from(e as Map)).toList(); _loading = false; }); } catch (_) { if (mounted) setState(() => _loading = false); } }
  Future<void> _create() async { final user = supabase.auth.currentUser; if (user == null) { _message('سجّل الدخول أولًا من أعلى المنتدى.'); return; } final result = await showDialog<Map<String, String>>(context: context, builder: (_) => const _CreateGroupDialog()); if (result == null) return; try { final group = await supabase.from('groups').insert({'owner_id': user.id, 'name': result['name'], 'description': result['description']}).select('id').single(); await supabase.from('group_members').insert({'group_id': group['id'], 'user_id': user.id, 'role': 'owner'}); _load(); } catch (_) { if (mounted) _message('تعذر إنشاء الجروب.'); } }
  Future<void> _join(Map<String, dynamic> group) async { final user = supabase.auth.currentUser; if (user == null) { _message('سجّل الدخول أولًا من أعلى المنتدى.'); return; } try { await supabase.from('group_members').upsert({'group_id': group['id'], 'user_id': user.id, 'status': group['is_private'] == true ? 'pending' : 'active'}); if (mounted) _message(group['is_private'] == true ? 'تم إرسال طلب الانضمام.' : 'انضممت إلى الجروب.'); } catch (_) { if (mounted) _message('أنت عضو بالفعل أو تعذر الانضمام.'); } }
  void _message(String text) => ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(text)));
  @override Widget build(BuildContext context) => Column(children: [Padding(padding: const EdgeInsets.fromLTRB(16, 16, 16, 10), child: Row(children: [const Expanded(child: Text('جروبات مفيدة', style: TextStyle(fontSize: 19, fontWeight: FontWeight.w800))), FilledButton.icon(onPressed: _create, icon: const Icon(Icons.add_rounded), label: const Text('جروب جديد'))])), Expanded(child: _loading ? const Center(child: CircularProgressIndicator()) : _groups.isEmpty ? const AppEmptyState(icon: Icons.groups_outlined, title: 'لا توجد جروبات بعد', message: 'أنشئ أول مساحة تجمع أصحاب الاهتمام الواحد.') : ListView.builder(padding: const EdgeInsets.fromLTRB(16, 0, 16, 28), itemCount: _groups.length, itemBuilder: (_, i) { final g = _groups[i]; final p = (g['profiles'] as Map?)?.cast<String, dynamic>() ?? {}; return Padding(padding: const EdgeInsets.only(bottom: 10), child: AppCard(padding: const EdgeInsets.all(16), child: Row(children: [AppIconBadge(icon: g['is_private'] == true ? Icons.lock_outline : Icons.groups_rounded, size: 48), const SizedBox(width: 12), Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(g['name']?.toString() ?? '', style: const TextStyle(fontWeight: FontWeight.w800, fontSize: 16)), const SizedBox(height: 4), Text(g['description']?.toString() ?? '', maxLines: 2, overflow: TextOverflow.ellipsis), const SizedBox(height: 5), Text('${g['member_count'] ?? 1} أعضاء · بواسطة ${p['full_name'] ?? p['username'] ?? 'عضو'}', style: Theme.of(context).textTheme.bodySmall)])), IconButton(onPressed: () => _join(g), icon: const Icon(Icons.arrow_forward_ios_rounded, size: 18))]))); }))]);
}

class _CreateGroupDialog extends StatefulWidget { const _CreateGroupDialog(); @override State<_CreateGroupDialog> createState() => _CreateGroupDialogState(); }
class _CreateGroupDialogState extends State<_CreateGroupDialog> { final _name = TextEditingController(); final _desc = TextEditingController(); @override void dispose() { _name.dispose(); _desc.dispose(); super.dispose(); } @override Widget build(BuildContext context) => AlertDialog(title: const Text('جروب جديد'), content: SingleChildScrollView(child: Column(mainAxisSize: MainAxisSize.min, children: [TextField(controller: _name, decoration: const InputDecoration(labelText: 'اسم الجروب')), const SizedBox(height: 12), TextField(controller: _desc, maxLines: 3, decoration: const InputDecoration(labelText: 'وصف مختصر'))])), actions: [TextButton(onPressed: () => Navigator.pop(context), child: const Text('إلغاء')), FilledButton(onPressed: () { if (_name.text.trim().length >= 2) Navigator.pop(context, {'name': _name.text.trim(), 'description': _desc.text.trim()}); }, child: const Text('إنشاء'))]); }
